"""Inspectable device inverse-design extension, using actual solver/search outputs."""
from pathlib import Path
import json,re
import numpy as np
R=Path(__file__).resolve().parent
s=json.loads((R/'results/inverse/summary.json').read_text());d=json.loads((R/'results/inverse/dataset.json').read_text());a=json.loads((R/'models/research_device_surrogate.json').read_text())
css=re.search(r'<style>(.*?)</style>',(R/'web/benchmark.html').read_text(),re.S)[1]
html=r'''<!doctype html><html lang="en" translate="no"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="google" content="notranslate"><title>REFLEX — Device research loop</title><style>__CSS__ input[type=range]{width:100%;accent-color:#225dff;padding:0}.loopstep{display:inline-block;border:1px solid #89979d;padding:12px 15px}.blue{color:#225dff}.devices{display:flex;height:115px;border:1px solid #142838;margin:22px 0}.devices div{width:50%;padding:18px;background:#dce5fb}.devices div+div{background:#e9d9bd}code{font:12px Menlo,monospace}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.twocol>*{min-width:0}#learning{overflow-x:auto;max-width:100%}#prediction{overflow-wrap:anywhere;font-size:clamp(14px,2vw,22px)!important}.legend{display:flex;gap:18px;font-size:13px}button:disabled{opacity:.45}video{width:100%}</style>
<nav><b>REFLEX.</b><span><a href="http://127.0.0.1:8765/benchmark.html">Metrology evidence</a><a href="#search">Design search</a><a href="#model">Learned model</a><a href="#roadmap">R&D roadmap</a></span></nav><main><section><div class="eyebrow">Device R&D extension / actual physics simulation / 11 Nov 2026</div><h1>Learn from each experiment.<br>Design towards a target.</h1><p class="lead">From predicting a process to proposing a device: specify electrical behavior, simulate candidate structures, train a surrogate, and choose the next experiment.</p><div class="flow"><b>Target I–V</b>→<b>Doping & geometry</b>→<b>Physics solver</b>→<b>Learned posterior</b>→<b>Next candidate</b></div><p class="small">Executed proof of the loop: a basic 1D silicon p–n diode with standard Gaussian-process expected improvement. Advanced transistors, fabricated devices and improved commercial chips are future stages.</p></section>
<section><div class="eyebrow">01 / Measured in this simulator experiment</div><div class="grid"><article class="card"><span class="tag">Equal 32-query budget · vs random</span><strong class="number">97.19% ↓</strong><h3>Mean target-matching error</h3><p>Mean squared log-current mismatch: 0.012410 → 0.000348. This measures closeness to a prescribed I–V target, not chip speed, power or yield.</p></article><article class="card"><span class="tag">All search seeds included</span><strong class="number">5 / 5</strong><h3>Searches beat random</h3><p>Each pair starts from the same eight designs. Both methods query 32 of 192 candidate designs. No losing seed was removed.</p><p class="small">Five search paths share one design pool. No broad statistical or state-of-the-art superiority claim.</p></article><article class="card"><span class="tag">Actual DEVSIM solves</span><strong class="number">256</strong><h3>Generated device designs</h3><p>192 candidates +64 held-out surrogate tests. Separate target reference and double-density mesh rerun. Zero solver failures.</p><p class="small">All pool generation incurs compute cost. Offline query counts are not measured wall-clock savings.</p></article></div></section>
<section id="search"><div class="eyebrow">02 / Replay the actual recorded design search</div><div class="toolbar"><h2>Fewer guesses. A closer electrical target.</h2><label>Paired seed<select id="seed"><option>11</option><option>23</option><option>37</option><option>51</option><option>71</option></select></label></div><div class="controls"><button id="play">Replay acquisition</button><button class="secondary" id="reset">Reset to 8 designs</button><label style="flex:1">Acquired labels: <strong id="budgetLabel">8</strong><input id="budget" type="range" min="8" max="32" value="8" step="1"></label></div><div class="twocol"><div><svg id="searchChart" role="img" aria-label="Best target mismatch versus acquired designs"></svg><div class="legend"><span class="blue">● Standard GP / expected improvement</span><span>● Random search</span></div><p class="small">This is a replay of actual saved query decisions, not a live simulator call. Objective: mean squared difference between predicted-device and target log10 currents at 0.2,0.4,0.5V. Lower is better.</p></div><div><h3>Current best GP-selected design</h3><div class="devices"><div>P region<br><strong id="na"></strong><br><small>acceptors / cm³</small></div><div>N region<br><strong id="nd"></strong><br><small>donors / cm³</small></div></div><p>Length: <b id="length"></b> µm · illustrative1D cross section</p><svg id="ivChart" role="img" aria-label="Target and selected device current voltage curves"></svg><div class="legend"><span>● Target reference</span><span class="blue">● Solver result of selected design</span></div><p class="small">Current density uses the example's1D unit-area convention. Absolute current requires a defined device area.</p></div></div><div class="scroll"><table><thead><tr><th>Seed</th><th>Random loss @32</th><th>GP loss @32</th><th>Relative reduction</th></tr></thead><tbody id="outcomes"></tbody></table></div></section>
<section id="model"><div class="eyebrow">03 / Data changes the model</div><h2>A learned posterior you can actually run.</h2><div class="twocol"><div><span class="tag">Live browser inference · saved 32-design posterior · seed 11</span><p>Move the structure parameters. The learned Matérn GP posterior evaluates locally from its saved training data and coefficients. This is model inference; it does not invoke the physical solver.</p><label>Acceptor doping: log10(Na / cm⁻³)<input id="pna" type="range" min="16" max="18" step=".01" value="17.59"><output id="vna"></output></label><label>Donor doping: log10(Nd / cm⁻³)<input id="pnd" type="range" min="16" max="18" step=".01" value="17.29"><output id="vnd"></output></label><label>Device length (µm)<input id="plen" type="range" min=".1" max="1" step=".001" value=".426"><output id="vlen"></output></label><div class="dark"><h3>Predicted log10 current density</h3><p id="prediction" style="font:22px Menlo,monospace"></p><p class="small">0.2V /0.4V /0.5V. Prediction quality is limited away from the search region; always verify candidates with the simulator.</p></div></div><div><h3>Does accumulating data help?</h3><div id="learning"></div><p>At 32 labels, the GP search's mean held-out log-current prediction RMSE falls from 2.621 to1.834: <b>30.03% lower than its 8-label model.</b></p><p>Random sampling's 32-label model scores 1.764, better for this global prediction task. Goal-directed search improves target matching; it does not win every measure of model quality.</p><p class="small">Test 64 designs remain outside all acquired training sets. These errors are in log10 units and remain large; this is a small-data simulator demonstration, not a qualified global device model.</p></div></div><details><summary>Numerical checks and exact scope</summary><p>DEVSIM 2.11.2 solves Poisson and electron/hole drift-diffusion equations with SRH recombination at 300 K. The upstream simple-physics model uses constant mobility and omits calibrated high-field, tunnelling, quantum and breakdown effects. Design bounds: p/n doping 10¹⁶–10¹⁸cm⁻³, length 0.1–1µm. The target is generated from a known reference design, not a specification for a novel chip.</p><p>Worst current-conservation imbalance across the 256-design pool: 0.432%. Doubling mesh density changes the final selected design's sampled currents by at most 0.0051%. Numerical consistency does not establish physical calibration or manufacturability.</p><p>The GP optimizer is standard prior art, not a proprietary breakthrough. Our new implementation combines the simulator, acquisition history, independent held-out evaluation, portable posterior export and inspectable replay. It is separate from the delay-aware metrology experiment; a combined physical-experiment loop is future work.</p></details></section>
<section id="roadmap"><div class="eyebrow">04 / How this becomes a device R&D engine</div><h2>Target a better device. Learn from the real result.</h2><div class="grid"><article class="card"><span class="tag">Implemented in this prototype</span><h3>Electrical target → candidate design</h3><p>Parameterized doping and geometry, physical simulation, persisted training data, updated GP posterior and query selection. Full trace and failures are retained.</p></article><article class="card"><span class="tag warn">Next validation stage</span><h3>Simulation → real experiment</h3><p>Fit simulation-to-measurement residuals using aligned device, recipe and instrument records. Use REFLEX's timestamp discipline when experimental results arrive later. Reject candidates outside process constraints.</p></article><article class="card"><span class="tag warn">Scale hypothesis</span><h3>One device family → reusable experience</h3><p>Extend to a calibrated transistor family and objectives such as on-current, leakage and capacitance. Transfer reusable data and uncertainty across compatible designs, with checks for negative transfer.</p></article></div><div class="dark"><h3>Proposed first R&D customer</h3><p>A device/TCAD engineering team exploring doping or geometry under fixed electrical constraints. Measure solver calls to an agreed feasible target, confirmation rate on a finer calibrated solver, and eventually physical experiment count. Those are the operational metrics to price, rather than an invented chip-performance percentage.</p><p>Potential advantage: consented experiment histories, process constraints and calibrated simulation-to-reality corrections. Data access, transfer and commercial demand remain to be established.</p></div><h3>Why the direction is technically credible</h3><p>A 2026 HBT study combines uncertainty-aware surrogates and active learning to propose epitaxial doping profiles. AgenticTCAD explores automated device optimization. These show prior work and competition; their results are not REFLEX results.</p><p><a href="https://doi.org/10.1007/s10825-026-02510-x">2026 HBT paper ↗</a> · <a href="https://arxiv.org/abs/2512.23742">AgenticTCAD ↗</a> · <a href="https://github.com/devsim/devsim">DEVSIM ↗</a></p><p><a class="button" href="https://github.com/2fe2000/reflex-metrology/tree/main/research">Code, protocol & evidence →</a></p><p class="small">Private repository by owner choice. No fabricated semiconductor, customer deployment or measured R&D-cycle cost saving.</p></section></main><footer>REFLEX / Device research loop / Frozen recorded experiment + live local surrogate inference.</footer>
<script>const S=__SUMMARY__,D=__DATA__,A=__MODEL__,$=id=>document.getElementById(id);let timer=null;function lineChart(el,series,xmin,xmax,ymin,ymax,xlabel,ylabel){let X=v=>65+(v-xmin)/(xmax-xmin)*540,Y=v=>260-(v-ymin)/(ymax-ymin)*215,t='<rect width="660" height="320" fill="#f4f1e9"/>';for(let i=0;i<5;i++){let v=ymin+(ymax-ymin)*i/4;t+=`<line x1="65" x2="605" y1="${Y(v)}" y2="${Y(v)}" stroke="#cbd0cc"/><text x="55" y="${Y(v)+4}" text-anchor="end" fill="#5c6870" font-size="11">${v.toFixed(2)}</text>`}for(let i=0;i<5;i++){let v=xmin+(xmax-xmin)*i/4;t+=`<text x="${X(v)}" y="284" text-anchor="middle" fill="#5c6870" font-size="12">${v.toFixed(xmax<=1?2:0)}</text>`}for(let s of series)t+=`<polyline points="${s.values.map(p=>[X(p[0]),Y(p[1])].join(',')).join(' ')}" fill="none" stroke="${s.color}" stroke-width="3"/>`;t+=`<text x="65" y="20" fill="#142838" font-size="12">${ylabel}</text><text x="335" y="313" text-anchor="middle" fill="#5c6870" font-size="12">${xlabel}</text>`;el.setAttribute('viewBox','0 0 660 325');el.innerHTML=t}function draw(){let seed=+$('seed').value,n=+$('budget').value;$('budgetLabel').textContent=n;let ts=S.traces.filter(t=>t.seed===seed),ei=ts.find(t=>t.method==='expected_improvement'),r=ts.find(t=>t.method==='random');let all=ts.flatMap(t=>t.trace.map(x=>Math.log10(x.best_loss)));lineChart($('searchChart'),[{values:r.trace.filter(x=>x.labels<=n).map(x=>[x.labels,Math.log10(x.best_loss)]),color:'#89979d'},{values:ei.trace.filter(x=>x.labels<=n).map(x=>[x.labels,Math.log10(x.best_loss)]),color:'#225dff'}],8,32,Math.min(...all)-.3,Math.max(...all)+.3,'Acquired design labels','log10 best target MSE · lower is better');let idx=ei.trace.find(x=>x.labels===n).best_index,b=D.records[idx];$('na').textContent=(10**b.parameters[0]).toExponential(2);$('nd').textContent=(10**b.parameters[1]).toExponential(2);$('length').textContent=b.parameters[2].toFixed(3);let curve=x=>x.filter(p=>p[0]>=.05).map(p=>[p[0],Math.log10(Math.max(p[1],1e-30))]),p=curve(b.curve),q=curve(D.target.curve),vals=[...p,...q].map(p=>p[1]);lineChart($('ivChart'),[{values:q,color:'#89979d'},{values:p,color:'#225dff'}],.05,.5,Math.min(...vals)-.4,Math.max(...vals)+.4,'Applied bias (V)','log10 current density (A/cm²)')}function predict(){let na=+$('pna').value,nd=+$('pnd').value,l=+$('plen').value;$('vna').textContent=na.toFixed(2);$('vnd').textContent=nd.toFixed(2);$('vlen').textContent=l.toFixed(3);let x=[(na-16)/2,(nd-16)/2,(l-.1)/.9],k=A.training_X.map(v=>{let r=Math.sqrt(v.reduce((s,z,i)=>s+((x[i]-z)/A.length_scale[i])**2,0)),z=Math.sqrt(5)*r;return(1+z+z*z/3)*Math.exp(-z)}),y=[0,1,2].map(j=>k.reduce((s,v,i)=>s+v*A.alpha[i][j],0)*A.y_std[j]+A.y_mean[j]);$('prediction').textContent=y.map(v=>v.toFixed(3)).join(' / ')}$('outcomes').innerHTML=S.outcomes.map(o=>`<tr><td>${o.seed}</td><td>${o.random.toFixed(6)}</td><td>${o.expected_improvement.toFixed(6)}</td><td class="good">${o.improvement_pct.toFixed(2)}%</td></tr>`).join('');$('learning').innerHTML='<table><tr><th>Acquired labels</th><th>GP search model</th><th>Random model</th></tr>'+[8,16,24,32].map(n=>'<tr><td>'+n+'</td>'+['expected_improvement','random'].map(m=>{let v=S.checkpoints.filter(c=>c.labels===n&&c.method===m);return'<td>'+(v.reduce((s,c)=>s+c.rmse,0)/v.length).toFixed(3)+'</td>'}).join('')+'</tr>').join('')+'</table><p class="small">Mean held-out log10-current RMSE over five seeds; lower is better.</p>';$('seed').onchange=draw;$('budget').oninput=draw;function stop(){clearInterval(timer);timer=null;$('play').textContent='Replay acquisition'}$('play').onclick=()=>{if(timer){stop();return}if(+$('budget').value===32)$('budget').value=8;$('play').textContent='Pause replay';timer=setInterval(()=>{let n=+$('budget').value;if(n>=32){stop();return}$('budget').value=n+1;draw()},350)};$('reset').onclick=()=>{stop();$('budget').value=8;draw()};['pna','pnd','plen'].forEach(id=>$(id).oninput=predict);draw();predict();</script></html>'''
html=html.replace('__CSS__',css).replace('__SUMMARY__',json.dumps(s)).replace('__DATA__',json.dumps(d)).replace('__MODEL__',json.dumps(a))
for p in [R/'web/research.html',R/'deliverables/REFLEX_device_research.html']:p.write_text(html)
# Add a focused research cross-link while preserving the industrial benchmark page.
p=R/'build_customer_page.py';text=p.read_text();text=text.replace('<a href="#value">Customer value</a>','<a href="#value">Customer value</a><a href="http://127.0.0.1:8765/research.html">Device R&D</a>');p.write_text(text)
print('Research page ready: actual search replay + learned-posterior inference.')
